using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B4PolishReview {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-09_B4_LayoutPolish/";static Vector3 origin=new Vector3(0,-66,0);static JObject Plan()=>JObject.Parse(File.ReadAllText(R+"/SourceAssets/B4_LayoutPolish/layout.json"));
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");return s;}
 static bool Free(Vector3 p){if(!Physics.Raycast(p+Vector3.up*.30f,Vector3.down,out var h,.55f,~0,QueryTriggerInteraction.Ignore)||h.point.y<p.y-.10f||h.point.y>p.y+.24f)return false;return !Physics.CheckCapsule(p+Vector3.up*.43f,p+Vector3.up*1.50f,.32f,~0,QueryTriggerInteraction.Ignore);}
 static object Travel(CharacterController cc,GameObject player,string id,List<Vector3> route){cc.enabled=false;player.transform.position=route[0]+Vector3.up*(cc.height*.5f-cc.center.y+.04f);cc.enabled=true;Physics.SyncTransforms();int steps=0,segment=0;float remaining=0;bool pass=true;Vector3 target=route[0];foreach(var to in route.Skip(1)){target=to;segment++;int limit=Mathf.CeilToInt(Vector3.Distance(player.transform.position,to)/.09f)+60;for(int i=0;i<limit;i++){var d=to-player.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.04f)break;cc.Move(d.normalized*Mathf.Min(.09f,remaining)+Vector3.down*.065f);steps++;}if(remaining>.12f){pass=false;break;}}for(int i=0;i<10;i++)cc.Move(Vector3.down*.04f);float bottom=player.transform.position.y+cc.center.y-cc.height*.5f;float err=bottom-target.y;if(Mathf.Abs(err)>.32f)pass=false;cc.enabled=false;return new{id,passed=pass,steps,segment,remaining,heightError=err,end=new[]{player.transform.position.x,bottom,player.transform.position.z}};}
 public static object Walk(){var s=Check();var plan=Plan();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var saved=player.transform.position;bool enabled=cc.enabled;var results=new List<object>();var paths=new List<object>();var failures=new List<string>();cc.enabled=false;Physics.SyncTransforms();
  try{
   foreach(var t in plan["tunnels"]){var a=origin+new Vector3((float)t["p"][0],0,-(float)t["p"][1]);var b=origin+new Vector3((float)t["q"][0],0,-(float)t["q"][1]);foreach(bool reverse in new[]{false,true})results.Add(Travel(cc,player,(string)t["id"]+(reverse?"_reverse":"_forward"),new List<Vector3>{reverse?b:a,reverse?a:b}));}
   foreach(var room in plan["rooms"]){string id=(string)room["id"];float rad=(float)room["r"],cell=.38f;int n=Mathf.CeilToInt(rad*2/cell)+1;Vector3 center=origin+new Vector3((float)room["x"],0,-(float)room["v"]);var valid=new bool[n*n];Vector3 Pos(int i)=>center+new Vector3(-rad+(i%n)*cell,0,-rad+(i/n)*cell);for(int i=0;i<valid.Length;i++)valid[i]=(Pos(i)-center).sqrMagnitude<(rad-.12f)*(rad-.12f)&&Free(Pos(i));
    var portalDoors=room["doors"].Select(d=>center+new Vector3((float)d["x"],0,(float)d["z"])).ToArray();var access=plan["workspaces"].Where(q=>(string)q["room"]==id).ToArray();var doors=portalDoors.Concat(access.Select(q=>center+new Vector3((float)q["point"][0],0,(float)q["point"][2]))).ToArray();int Nearest(Vector3 p)=>Enumerable.Range(0,valid.Length).Where(i=>valid[i]).OrderBy(i=>(Pos(i)-p).sqrMagnitude).First();
    for(int d=1;d<doors.Length;d++){int start=Nearest(doors[0]),end=Nearest(doors[d]);if(d>=portalDoors.Length&&Vector3.Distance(Pos(end),doors[d])>.70f){failures.Add(id+" workspace not accessible "+(string)access[d-portalDoors.Length]["name"]+" delta="+Vector3.Distance(Pos(end),doors[d]));continue;}var prev=Enumerable.Repeat(-1,n*n).ToArray();var queue=new Queue<int>();queue.Enqueue(start);prev[start]=start;
     while(queue.Count>0&&prev[end]<0){int cur=queue.Dequeue(),x=cur%n,z=cur/n;foreach(var pair in new[]{new[]{1,0},new[]{-1,0},new[]{0,1},new[]{0,-1}}){int xx=x+pair[0],zz=z+pair[1];if(xx<0||xx>=n||zz<0||zz>=n)continue;int to=zz*n+xx;if(!valid[to]||prev[to]>=0)continue;prev[to]=cur;queue.Enqueue(to);}}
     if(prev[end]<0){failures.Add(id+" unreachable door "+d);continue;}var raw=new List<Vector3>();for(int at=end;;at=prev[at]){raw.Add(Pos(at));if(at==start)break;}raw.Reverse();var route=new List<Vector3>{doors[0]};for(int i=0;i<raw.Count;i++)if(i==0||i==raw.Count-1||Vector3.Cross(raw[i]-raw[i-1],raw[i+1]-raw[i]).sqrMagnitude>.001f)route.Add(raw[i]);if(d<portalDoors.Length)route.Add(doors[d]);paths.Add(new{id=id+"_door_0_"+d,points=route.Select(v=>new[]{v.x,v.y,v.z}).ToArray()});results.Add(Travel(cc,player,id+(d<portalDoors.Length?"_door_0_"+d:"_work_"+(string)access[d-portalDoors.Length]["name"]),route));if(d<portalDoors.Length){route.Reverse();results.Add(Travel(cc,player,id+"_door_"+d+"_0",route));}
    }
   }
   foreach(string code in new[]{"VA","VB"}){var room=plan["rooms"].Single(r=>(string)r["id"]==code);var c=origin+new Vector3((float)room["x"],0,-(float)room["v"]);var pts=new List<Vector3>{c+new Vector3(-.96f,0,-2.10f)};for(int f=0;f<8;f++){float dir=f%2==0?1:-1,x=f%2==0?-.96f:.96f,y=(f+1)*2.125f;pts.Add(c+new Vector3(x,y,dir*2.38f));if(f<7)pts.Add(c+new Vector3(-x,y,dir*2.38f));}pts.Add(c+new Vector3(0,17,-2.38f));pts.Add(c+new Vector3(0,17,-4.0f));results.Add(Travel(cc,player,code+"_17m_up",pts));pts.Reverse();results.Add(Travel(cc,player,code+"_17m_down",pts));}
  }finally{cc.enabled=false;player.transform.position=saved;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}
  var result=new{results,planningFailures=failures};File.WriteAllText(O+"walk.json",JsonConvert.SerializeObject(result,Formatting.Indented));File.WriteAllText(O+"routes.json",JsonConvert.SerializeObject(paths,Formatting.Indented));return new{tested=results.Count,planningFailures=failures,failed=results.Count(x=>!(bool)x.GetType().GetProperty("passed").GetValue(x))};
 }
 static void Shot(string file,Vector3 pos,Vector3 target,float fov=85){var go=new GameObject("B4_FullReview_Temporary");go.hideFlags=HideFlags.HideAndDontSave;var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.useOcclusionCulling=false;c.nearClipPlane=.04f;c.farClipPlane=350;c.fieldOfView=fov;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+file+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Capture(){var s=Check();var plan=Plan();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);try{foreach(var r in plan["rooms"]){var center=origin+new Vector3((float)r["x"],0,-(float)r["v"]);var d=r["doors"][0];var dir=new Vector3((float)d["x"],0,(float)d["z"]).normalized;Shot((string)r["id"]+"_room",center+dir*((float)r["r"]-1.3f)+Vector3.up*1.7f,center+Vector3.up*1.2f,94);Shot((string)r["id"]+"_overview",center-dir*((float)r["r"]*.57f)+Vector3.up*((string)r["kind"]=="core"?4.7f:3.3f),center+dir*((float)r["r"]*.12f)+Vector3.up*.9f,94);}foreach(var t in plan["tunnels"]){var a=origin+new Vector3((float)t["p"][0],1.7f,-(float)t["p"][1]);var b=origin+new Vector3((float)t["q"][0],1.7f,-(float)t["q"][1]);Shot((string)t["id"],a+(b-a).normalized*2,b,78);}}finally{EditorSceneManager.OpenScene(s.path);}return new{images=54};}

 public static object Details(){var s=Check();var plan=Plan();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);int count=0;
  try{foreach(string code in new[]{"N01","E01","E02","W01","W02","S01","E03","VL","VA"}){var r=plan["rooms"].Single(q=>(string)q["id"]==code);var c=origin+new Vector3((float)r["x"],0,-(float)r["v"]);Vector3 p,t;
   switch(code){case "N01":p=new Vector3(-1,1.7f,.5f);t=new Vector3(0,1.8f,8);break;case "E01":p=new Vector3(-1,1.7f,-.4f);t=new Vector3(0,1.7f,6);break;case "E02":p=new Vector3(.5f,1.7f,-1);t=new Vector3(5.5f,1.1f,1.2f);break;case "W01":p=new Vector3(-2.2f,1.7f,-1.9f);t=new Vector3(-1.2f,1.3f,5);break;case "W02":p=new Vector3(1.5f,1.7f,0);t=new Vector3(-4.5f,1.3f,.5f);break;case "S01":p=new Vector3(-.4f,1.7f,.3f);t=new Vector3(1,1.7f,-5);break;case "E03":p=new Vector3(-1,1.7f,-.5f);t=new Vector3(0,1.2f,-5.5f);break;case "VL":p=new Vector3(0,1.7f,3.7f);t=new Vector3(0,1.4f,-1.5f);break;default:p=new Vector3(.96f,18.7f,-1.8f);t=new Vector3(0,18,-4.5f);break;}
   Shot(code+"_detail",c+p,c+t,78);count++;}
  }finally{EditorSceneManager.OpenScene(s.path);}return new{images=count};}
 public static object Roles(){var s=Check();var plan=Plan();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);var records=new List<object>();
 try{foreach(var p in plan["newPlacements"].Where(q=>(bool)q["primary"]||(string)q["model"]=="BX_ProjectileCabinet")){
  var r=plan["rooms"].Single(q=>(string)q["id"]==(string)p["room"]);var center=origin+new Vector3((float)r["x"],0,-(float)r["v"]);var pos=center+new Vector3((float)p["position"][0],0,(float)p["position"][2]);var rot=Quaternion.Euler(0,(float)p["yaw"],0);string name=(string)p["room"]+"_role_"+((string)p["name"]).Split('_').Last();bool booth=(string)p["model"]=="BX_ObservationBooth";
  Vector3 camera=booth?pos+rot*new Vector3(0,1.68f,.60f):pos+rot*new Vector3(1.1f,1.68f,(float)p["size"][2]*.5f+2.15f);Vector3 target=booth?pos+rot*new Vector3(0,1.45f,-7):pos+Vector3.up*1.15f;
  bool cabinet=(string)p["model"]=="BX_ProjectileCabinet";if(cabinet){camera=pos+rot*new Vector3(.35f,1.25f,1.45f);target=pos+Vector3.up*1.0f;}
  Shot(name,camera,target,booth?84:(cabinet?82:70));records.Add(new{file=name+".png",name=(string)p["name"],view=booth?"연구원 관측석":"설비 사용면",position=new[]{camera.x,camera.y,camera.z}});
 }}finally{EditorSceneManager.OpenScene(s.path);}File.WriteAllText(O+"role_views.json",JsonConvert.SerializeObject(records,Formatting.Indented));return new{images=records.Count};}
}
